// Writers for the generated Solidity libraries and the Foundry test of a
// t != 4 permutation (yul/render.ts).

use super::schedule::{BuildResult, Layout};
use crate::field::{PRIME, hex};
use crate::huff::render::{Vector, render_vector_cases};
use crate::round_constants::Params;

const HEADER: &str = "// SPDX-License-Identifier: MIT
// This file is generated by generator/yul/generate.ts. Do not edit manually.
";

const SECURITY: &str = "Security: https://github.com/zemse/poseidon2-evm/blob/main/SECURITY.md";

/// The t = 4 library keeps its hash_1 / hash_2 / hash_3 / poseidon2_core
/// API.
pub fn render_hash_library(result: &BuildResult) -> String {
    format!(
        "{HEADER}
pragma solidity >=0.6.0;

/// @notice Poseidon2 hash function library optimized in Yul assembly
/// @dev Internal functions can be inlined without deploying a contract
/// @dev Every add / mul in the assembly was checked by the generator's bound tracker to fit in uint256
/// {SECURITY}
library LibPoseidon2Yul {{
    function hash_1(uint256 x) internal pure returns (uint256) {{
        return poseidon2_core(x, 0, 0, 1 << 64);
    }}

    function hash_2(uint256 x, uint256 y) internal pure returns (uint256) {{
        return poseidon2_core(x, y, 0, 2 << 64);
    }}

    function hash_3(uint256 x, uint256 y, uint256 z) internal pure returns (uint256) {{
        return poseidon2_core(x, y, z, 3 << 64);
    }}

    function poseidon2_core(uint256 s0, uint256 s1, uint256 s2, uint256 s3) internal pure returns (uint256 result) {{
        assembly {{
{}
        }}
    }}
}}
",
        result.lines.join("\n")
    )
}

pub fn library_name(t: usize) -> String {
    format!("LibPoseidon2YulT{t}")
}

pub fn render_array_library(params: &Params, layout: &Layout, result: &BuildResult) -> String {
    let (t, rounds_f, rounds_p) = (params.t, params.rounds_f, params.rounds_p);
    let name = library_name(t);
    let placement = if layout.stack_elements == t {
        "the state is held in Yul locals".to_string()
    } else {
        format!(
            "elements 0 .. {} are held in Yul locals, the rest in the array",
            layout.stack_elements as i64 - 1
        )
    };
    let table = if layout.diag_in_memory > 0 {
        format!(
            "\n/// @dev {} of the {t} internal diag constants are kept in free memory (not allocated) to stay within the code size limit",
            layout.diag_in_memory
        )
    } else {
        String::new()
    };
    format!(
        "{HEADER}
pragma solidity >=0.6.0;

/// @notice Poseidon2 permutation for BN254 with t = {t}, Rf = {rounds_f}, Rp = {rounds_p}, optimized in Yul assembly
/// @dev Permutes `state` in place; inputs are reduced mod PRIME, {placement}
/// @dev Every add / mul in the assembly was checked by the generator's bound tracker to fit in uint256{table}
/// {SECURITY}
library {name} {{
    function permute(uint256[{t}] memory state) internal pure {{
        assembly {{
{}
        }}
    }}
}}
",
        result.lines.join("\n")
    )
}

/// with_huff adds a fuzz test against the Huff permutation of the same
/// width.
pub fn render_forge_test(params: &Params, vectors: &[Vector], with_huff: bool) -> String {
    let t = params.t;
    let lib = library_name(t);
    let wrapper = format!("Poseidon2YulT{t}");
    let cases = render_vector_cases(t, vectors);
    let huff_import = if with_huff {
        "import {HuffDeployer} from \"foundry-huff/HuffDeployer.sol\";\n"
    } else {
        ""
    };
    let huff_field = if with_huff {
        "    address private huff;\n"
    } else {
        ""
    };
    let huff_deploy = if with_huff {
        format!("        huff = HuffDeployer.deploy(\"bn254/huff/t{t}/Poseidon2\");\n")
    } else {
        String::new()
    };
    let permute_huff = if with_huff {
        format!(
            "
    function _permuteHuff(uint256[{t}] memory input) internal view returns (uint256[{t}] memory out) {{
        (bool ok, bytes memory ret) = huff.staticcall(abi.encode(input));
        require(ok, \"huff permutation call failed\");
        out = abi.decode(ret, (uint256[{t}]));
    }}
"
        )
    } else {
        String::new()
    };
    let fuzz = if with_huff {
        format!(
            "
    /// @dev the Yul and Huff permutations of the same width must agree on any input
    /// forge-config: default.fuzz.runs = 1000
    function testFuzz_matches_huff(uint256[{t}] memory input) public view {{
        assertEq(_permute(input), _permuteHuff(input), \"yul != huff\");
    }}
"
        )
    } else {
        String::new()
    };
    format!(
        "{HEADER}pragma solidity ^0.8.13;

import {{Test}} from \"forge-std/Test.sol\";
{huff_import}import {{{lib}}} from \"../src/bn254/yul/t{t}/{lib}.sol\";

/// @notice Deployed in the test so the gas and code size of a contract using the library are measured
contract {wrapper} {{
    function permute(uint256[{t}] memory state) external pure returns (uint256[{t}] memory) {{
        {lib}.permute(state);
        return state;
    }}
}}

/// @notice Vectors come from the BigInt reference permutation in generator/shared/reference.ts
contract {wrapper}Test is Test {{
    uint256 constant PRIME = {prime};

    {wrapper} private perm;
{huff_field}
    function setUp() public {{
        perm = new {wrapper}();
{huff_deploy}    }}

    function _permute(uint256[{t}] memory input) internal view returns (uint256[{t}] memory) {{
        return perm.permute(input);
    }}
{permute_huff}
    function assertEq(uint256[{t}] memory a, uint256[{t}] memory b, string memory err) internal pure {{
        for (uint256 i = 0; i < {t}; i++) {{
            assertEq(a[i], b[i], err);
        }}
    }}
{cases}

    /// @dev inputs at or above PRIME are reduced by the library
    function test_input_sanitization() public view {{
        uint256[{t}] memory a;
        uint256[{t}] memory b;
        for (uint256 i = 0; i < {t}; i++) {{
            a[i] = i + 5;
            b[i] = PRIME + i + 5;
        }}
        assertEq(_permute(a), _permute(b), \"sanitization\");
        for (uint256 i = 0; i < {t}; i++) {{
            a[i] = type(uint256).max % PRIME;
            b[i] = type(uint256).max;
        }}
        assertEq(_permute(a), _permute(b), \"sanitization max\");
    }}
{fuzz}}}
",
        prime = hex(PRIME),
    )
}
